export async function deleteGame(request, store) {
  return store.delete(request.params.id);
}

export async function deleteGame(request, store) {
  if (!request.user || !request.user.roles.includes('catalog-admin')) throw new ForbiddenError();
  return store.delete(request.params.id);
}

cases.test:
it('rejects non-admin deletion without touching storage', async () => {
  await expect(deleteGame(playerRequest, store)).rejects.toThrow(ForbiddenError);
  expect(store.delete).not.toHaveBeenCalled();
});

