export function searchGames(db, query) {
  return db.exec(`SELECT * FROM games WHERE title LIKE '%${query}%'`);
}

export function searchGames(db, query) {
  return db.prepare('SELECT * FROM games WHERE title LIKE ?').all(`%${query}%`);
}

cases.test:
it('binds hostile input as data', () => {
  searchGames(db, "%' OR 1=1 --");
  expect(db.prepare().all).toHaveBeenCalledWith("%%' OR 1=1 --%");
});

