export async function extract(root, entry) {
  return writeFile(join(root, entry.name), entry.data);
}

export async function extract(root, entry) {
  const base = resolve(root) + sep;
  const target = resolve(root, entry.name);
  if (!target.startsWith(base)) throw new Error('unsafe archive path');
  return writeFile(target, entry.data);
}

cases.test:
it('rejects traversal before writing', async () => {
  await expect(extract(root, { name: '../../escape', data })).rejects.toThrow('unsafe archive path');
  expect(writeFile).not.toHaveBeenCalled();
});

