export function restoreSession(serialized) {
  return eval(`(${serialized})`);
}

export function restoreSession(serialized) {
  const value = JSON.parse(serialized);
  if (!isSessionState(value)) throw new Error('invalid session state');
  return { score: value.score };
}

cases.test:
it('rejects executable and malformed input', () => {
  expect(() => restoreSession('{"__proto__":{"admin":true}}')).toThrow('invalid session state');
  expect({}.admin).toBeUndefined();
});

