export async function redeem(userId, rewardId) {
  if (!(await rewards.has(userId, rewardId))) await rewards.grant(userId, rewardId);
}

export async function redeem(userId, rewardId) {
  return rewards.insertIfAbsent({ userId, rewardId }, { unique: ['userId', 'rewardId'] });
}

cases.test:
it('atomically rejects concurrent duplicate redemption', async () => {
  const results = await Promise.allSettled([redeem(userId, rewardId), redeem(userId, rewardId)]);
  expect(results.filter(result => result.status === 'fulfilled')).toHaveLength(1);
});

