export async function download(url) {
  const file = await openTemporaryFile();
  await fetchToFile(url, file.path);
  return file.path;
}

export async function withDownload(url, consume) {
  const file = await openTemporaryFile();
  try {
    await fetchToFile(url, file.path);
    return await consume(file.path);
  } finally {
    await file.remove();
  }
}

cases.test:
it('removes temporary data after success and failure', async () => {
  await withDownload(url, consume);
  expect(file.remove).toHaveBeenCalled();
  consume.mockRejectedValueOnce(new Error('failed'));
  await expect(withDownload(url, consume)).rejects.toThrow('failed');
  expect(file.remove).toHaveBeenCalledTimes(2);
});

